import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CisoyQNf.js";var i=JSON.parse(`{"title":"SurfaceControlRegistry 调试功能使用指南","description":"介绍 SurfaceControlRegistry 的对象统计、Transaction 调用栈追踪和调试排查方法。","frontmatter":{"title":"SurfaceControlRegistry 调试功能使用指南","description":"介绍 SurfaceControlRegistry 的对象统计、Transaction 调用栈追踪和调试排查方法。","date":"2026-08-31T00:00:00.000Z","outline":"deep"},"headers":[],"relativePath":"blog/surfacecontrol-registry-debugging.md","filePath":"blog/surfacecontrol-registry-debugging.md","lastUpdated":0}`),a={name:`blog/surfacecontrol-registry-debugging.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="surfacecontrolregistry-调试功能使用指南" tabindex="-1">SurfaceControlRegistry 调试功能使用指南 <a class="header-anchor" href="#surfacecontrolregistry-调试功能使用指南" aria-label="Permalink to “SurfaceControlRegistry 调试功能使用指南”">​</a></h1><p>本文介绍 AOSP 中 <code>SurfaceControlRegistry</code> 提供的两类调试能力：</p><ol><li>统计进程内仍存活的 <code>SurfaceControl</code>，定位对象未及时释放的问题。</li><li>按 <code>SurfaceControl.Transaction</code> 方法名或 Surface 名称打印 Java 调用栈，定位是谁修改了 Surface。</li></ol><p>实现入口：<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/view/SurfaceControlRegistry.java" target="_blank" rel="noreferrer"><code>SurfaceControlRegistry.java</code></a>。</p><h2 id="_1-使用前提" tabindex="-1">1. 使用前提 <a class="header-anchor" href="#_1-使用前提" aria-label="Permalink to “1. 使用前提”">​</a></h2><p>调用栈调试只在 <code>debuggable</code> 构建中生效。Surface 注册表还需要由进程显式调用 <code>SurfaceControlRegistry.createProcessInstance(Context)</code> 创建，并要求调用者持有 <code>android.permission.READ_FRAME_BUFFER</code>。</p><p>当前 AOSP 中，WMShell 在初始化时创建注册表：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ShellInterfaceImpl.onInit()</span></span>
<span class="line"><span>    -&gt; ShellController.handleInit()</span></span>
<span class="line"><span>    -&gt; SurfaceControlRegistry.createProcessInstance()</span></span></code></pre></div><p>因此，注册表 dump 主要查看承载 WMShell 的 SystemUI 进程；它不是所有应用进程默认开启的全局服务。</p><p>调用栈调试的范围不同：<code>SurfaceControl.Transaction</code> 第一次创建时会读取调试属性，即使当前进程没有创建 Registry，<code>getProcessInstance()</code> 返回的 <code>NoOpRegistry</code> 仍会执行调用栈检查。因此只要是 debuggable 进程， 就可以用属性追踪该进程中的 Transaction 调用。</p><h2 id="_2-追踪-transaction-调用栈" tabindex="-1">2. 追踪 Transaction 调用栈 <a class="header-anchor" href="#_2-追踪-transaction-调用栈" aria-label="Permalink to “2. 追踪 Transaction 调用栈”">​</a></h2><h3 id="_2-1-按方法名过滤" tabindex="-1">2.1 按方法名过滤 <a class="header-anchor" href="#_2-1-按方法名过滤" aria-label="Permalink to “2.1 按方法名过滤”">​</a></h3><p><code>persist.wm.debug.sc.tx.log_match_call</code> 用于匹配 <code>SurfaceControl.Transaction</code> 的方法名， 例如 <code>setAlpha</code>、<code>setPosition</code>、<code>reparent</code>。</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setAlpha,setPosition</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SurfaceControlRegistry</span></span></code></pre></div><p>首次启用建议重启，使各进程在创建第一个 <code>Transaction</code> 时读取属性。已经启用后，修改过滤条件通常不需要再次重启。</p><p>关闭过滤：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span></code></pre></div><h3 id="_2-2-按-surface-名称过滤" tabindex="-1">2.2 按 Surface 名称过滤 <a class="header-anchor" href="#_2-2-按-surface-名称过滤" aria-label="Permalink to “2.2 按 Surface 名称过滤”">​</a></h3><p><code>persist.wm.debug.sc.tx.log_match_name</code> 用于匹配 Surface 名称。可以只设置名称，表示追踪该 Surface 的所有已埋点操作：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.android.systemui</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SurfaceControlRegistry</span></span></code></pre></div><p>两个属性同时设置时，调用名和 Surface 名称必须同时匹配：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setAlpha,setPosition</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.android.systemui</span></span></code></pre></div><p>过滤采用大小写不敏感的字符串包含匹配，不是正则表达式，也不会严格解析逗号列表。例如过滤值为 <code>alpha</code> 时，可能匹配到名称中包含 <code>alpha</code> 的其他方法或 Surface。</p><h3 id="_2-3-日志内容" tabindex="-1">2.3 日志内容 <a class="header-anchor" href="#_2-3-日志内容" aria-label="Permalink to “2.3 日志内容”">​</a></h3><p>命中后，Java 层通过 <code>Log.e(&quot;SurfaceControlRegistry&quot;, msg, new Throwable())</code> 输出调用栈。典型信息包括：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>setAlpha (tx=&lt;transaction-id&gt;  sc=&lt;surface-name&gt;) alpha=&lt;value&gt;</span></span>
<span class="line"><span>java.lang.Throwable</span></span>
<span class="line"><span>    at ...</span></span>
<span class="line"><span>    at ...</span></span></code></pre></div><p>字段含义：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td>方法名</td><td>被调用的 Transaction 操作，例如 <code>setAlpha</code>、<code>reparent</code></td></tr><tr><td><code>tx</code></td><td>Transaction ID，用于关联后续 <code>merge/apply</code></td></tr><tr><td><code>sc</code></td><td>被修改的 Surface 名称</td></tr><tr><td>其他参数</td><td>本次调用的属性值，例如坐标、透明度、裁剪区域</td></tr><tr><td>Java 堆栈</td><td>触发该 Transaction 操作的上层代码路径</td></tr></tbody></table><p>当前主要埋点包括：</p><ul><li>生命周期：<code>ctor</code>、<code>apply</code>、<code>merge</code>、<code>release</code></li><li>可见性和层级：<code>show</code>、<code>hide</code>、<code>setLayer</code>、<code>setRelativeLayer</code>、<code>reparent</code></li><li>几何属性：<code>setPosition</code>、<code>setScale</code>、<code>setMatrix</code>、<code>setCrop</code>、<code>setWindowCrop</code></li><li>外观属性：<code>setAlpha</code>、<code>setColor</code>、<code>setOpaque</code>、<code>setSecure</code></li><li>特效属性：<code>setCornerRadius</code>、<code>setBackgroundBlurRadius</code>、<code>setShadowRadius</code></li><li>帧时间：<code>setFrameTimeline</code>、<code>setFrameTimelineVsync</code></li></ul><p>不是所有 <code>Transaction</code> 方法都埋点，没有对应日志不代表方法一定没有执行。</p><h2 id="_3-追踪-transaction-的-apply-和-merge" tabindex="-1">3. 追踪 Transaction 的 apply 和 merge <a class="header-anchor" href="#_3-追踪-transaction-的-apply-和-merge" aria-label="Permalink to “3. 追踪 Transaction 的 apply 和 merge”">​</a></h2><p>仅追踪 <code>setAlpha</code> 等属性调用时，只能知道“哪里修改了 Transaction”，不能直接知道它最终何时提交。 将 <code>apply</code> 加入调用过滤值后，会进入 Transaction 聚合模式：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setAlpha,merge,apply</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setprop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> persist.wm.debug.sc.tx.log_match_name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reboot</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logcat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SurfaceControlRegistry</span></span></code></pre></div><p>执行流程：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Transaction.setAlpha()/merge()</span></span>
<span class="line"><span>    -&gt; 打印命中调用的 Java 堆栈</span></span>
<span class="line"><span>    -&gt; 将调用描述保存到 tx.mCalls</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Transaction.apply()</span></span>
<span class="line"><span>    -&gt; 打印 apply 的 Java 堆栈</span></span>
<span class="line"><span>    -&gt; 打印该 Transaction 已收集的调用</span></span>
<span class="line"><span>    -&gt; 清空 mCalls</span></span>
<span class="line"><span>    -&gt; nativeApplyTransaction()</span></span></code></pre></div><p>分析时先记录属性调用中的 <code>tx=&lt;id&gt;</code>，再搜索同一个 ID 的 <code>merge</code> 和 <code>apply</code>：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>属性修改位置 -&gt; Transaction ID -&gt; merge 到哪个 Transaction -&gt; 最终 apply 位置</span></span></code></pre></div><p>这对 Transition、BLASTBufferQueue 等“提前构造 Transaction、稍后合并或提交”的路径尤其有用。</p><h3 id="_3-1-blast-合并路径" tabindex="-1">3.1 BLAST 合并路径 <a class="header-anchor" href="#_3-1-blast-合并路径" aria-label="Permalink to “3.1 BLAST 合并路径”">​</a></h3><p><code>ViewRootImpl.mergeWithNextTransaction()</code> 会调用 <code>Transaction.onMergeWithNextTransaction(windowName)</code>。该方法通过 JNI 调用 native <code>SurfaceComposerClient::Transaction::enableDebugLogCallPoints()</code>，使 native 层在 Transaction 合并和 提交时输出：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Transaction &lt;id&gt; merged with transaction &lt;id&gt;</span></span>
<span class="line"><span>Transaction &lt;id&gt; applied</span></span></code></pre></div><p>native 日志 tag 同样是 <code>SurfaceControlRegistry</code>，可以和 Java 层日志一起过滤。</p><h2 id="_4-查看活动-surfacecontrol-列表" tabindex="-1">4. 查看活动 SurfaceControl 列表 <a class="header-anchor" href="#_4-查看活动-surfacecontrol-列表" aria-label="Permalink to “4. 查看活动 SurfaceControl 列表”">​</a></h2><h3 id="_4-1-通过-wmshell-dump" tabindex="-1">4.1 通过 WMShell dump <a class="header-anchor" href="#_4-1-通过-wmshell-dump" aria-label="Permalink to “4.1 通过 WMShell dump”">​</a></h3><p>当前版本使用：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span></span></code></pre></div><p>旧版本可能使用：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">adb</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> shell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dumpsys</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> activity</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SystemUIService</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WMShell</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dump</span></span></code></pre></div><p>调用流程：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ShellCommandHandler.dump()</span></span>
<span class="line"><span>    -&gt; ShellController.handleDump()</span></span>
<span class="line"><span>    -&gt; SurfaceControlRegistry.dump(100, false, pw)</span></span></code></pre></div><p>输出示例：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>SurfaceControlRegistry</span></span>
<span class="line"><span>----------------------</span></span>
<span class="line"><span>Listing oldest 3 of 3</span></span>
<span class="line"><span>  SysUiSurface (SomeController#createSurface) [12s ago]</span></span>
<span class="line"><span>  LeakedSurface (SurfaceControl.Builder) [8s ago]</span></span>
<span class="line"><span>  AnotherSurface (TransitionController) [2s ago]</span></span>
<span class="line"><span>sCallStackDebuggingInitialized=true</span></span>
<span class="line"><span>sCallStackDebuggingEnabled=false</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>每条 Surface 的含义：</p><table tabindex="0"><thead><tr><th>输出项</th><th>含义</th></tr></thead><tbody><tr><td>Surface 名称</td><td><code>SurfaceControl.getName()</code> 返回的调试名称</td></tr><tr><td>括号内容</td><td>创建或更新过的 <code>callsite</code></td></tr><tr><td><code>N s ago</code></td><td>加入当前进程 Registry 的时间</td></tr><tr><td><code>Listing oldest X of Y</code></td><td>当前记录总数和本次打印的最老对象数量</td></tr></tbody></table><p>WMShell 当前传入 <code>limit=100</code>、<code>runGc=false</code>。该 dump 不会主动触发 GC，也不显示完整的 SurfaceFlinger 层级、父子关系、Z 序和可见性；需要这些信息时使用 <code>dumpsys SurfaceFlinger</code> 或 Winscope。</p><h3 id="_4-2-数量阈值自动报告" tabindex="-1">4.2 数量阈值自动报告 <a class="header-anchor" href="#_4-2-数量阈值自动报告" aria-label="Permalink to “4.2 数量阈值自动报告”">​</a></h3><p>注册表默认在活动对象数达到 1024 时自动报告最老的 256 个对象。报告只触发一次，直到数量下降到 256 或以下后才允许再次触发，用于避免持续刷屏。</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1024 个活动 SurfaceControl</span></span>
<span class="line"><span>    -&gt; DefaultReporter.onMaxLayersExceeded()</span></span>
<span class="line"><span>    -&gt; 按注册时间排序</span></span>
<span class="line"><span>    -&gt; 输出最老的 256 个对象</span></span></code></pre></div><p>阈值报告在 <code>add()</code> 中通过 <code>System.out</code> 输出；主动 dump 则写入传入的 <code>PrintWriter</code>。因此只用 <code>adb logcat -s SurfaceControlRegistry</code> 可能看不到阈值报告，建议同时保留 WMShell dump 输出。</p><h2 id="_5-源码定位入口" tabindex="-1">5. 源码定位入口 <a class="header-anchor" href="#_5-源码定位入口" aria-label="Permalink to “5. 源码定位入口”">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>优先查看的类和方法</th></tr></thead><tbody><tr><td>Surface 数量持续增长</td><td><a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/view/SurfaceControl.java" target="_blank" rel="noreferrer"><code>SurfaceControl</code></a> 的 <code>assignNativeObject()</code>、<code>release()</code>、<code>finalize()</code>；<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/view/SurfaceControlRegistry.java" target="_blank" rel="noreferrer"><code>SurfaceControlRegistry</code></a> 的 <code>add/remove()</code></td></tr><tr><td>找谁调用了 <code>setAlpha</code> 等属性</td><td><a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/view/SurfaceControl.java" target="_blank" rel="noreferrer"><code>SurfaceControl.Transaction</code></a> 对应方法、<code>SurfaceControlRegistry.checkCallStackDebugging()</code></td></tr><tr><td>找 Transaction 最终提交位置</td><td><code>SurfaceControl.Transaction.apply()</code>、<code>SurfaceComposerClient::Transaction::apply()</code></td></tr><tr><td>找 Transaction 合并链路</td><td><code>SurfaceControl.Transaction.merge()</code>、<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/java/android/view/ViewRootImpl.java" target="_blank" rel="noreferrer"><code>ViewRootImpl</code></a> 的 <code>mergeWithNextTransaction()</code>、<code>BLASTBufferQueue::mergeWithNextTransaction()</code></td></tr><tr><td>找 dump 为什么没有内容</td><td><a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/libs/WindowManager/Shell/src/com/android/wm/shell/sysui/ShellController.java" target="_blank" rel="noreferrer"><code>ShellController</code></a> 的 <code>handleInit()/handleDump()</code>、<code>SurfaceControlRegistry.createProcessInstance()</code></td></tr></tbody></table><h2 id="_6-常见误区" tabindex="-1">6. 常见误区 <a class="header-anchor" href="#_6-常见误区" aria-label="Permalink to “6. 常见误区”">​</a></h2><ol><li><strong>Registry 不是 SurfaceFlinger 的全局 Layer 列表。</strong> 它只记录当前进程中的 Java <code>SurfaceControl</code> 包装对象。</li><li><strong>没有注册表不等于不能打印调用栈。</strong> 调用栈功能通过 <code>NoOpRegistry</code> 仍可执行；注册表 dump 则需要显式创建实例。</li><li><strong>不要把 <code>apply</code> 日志当作属性调用位置。</strong> 属性调用的 Java 堆栈才是修改发生的位置，<code>apply</code> 表示提交发生的位置。</li><li><strong><code>setTransparentRegionHint()</code> 当前日志标签存在复制错误。</strong> 源码中它使用了 <code>unsetFixedTransformHint</code> 作为调用名，过滤时需要注意这一点。</li><li><strong>阈值报告不是精确的 Layer 泄漏结论。</strong> 对象可能因为显式 <code>release</code>、finalize 或弱引用回收而从列表消失；需要结合 SurfaceFlinger dump 判断服务端 Layer 状态。</li></ol><h2 id="_7-相关测试" tabindex="-1">7. 相关测试 <a class="header-anchor" href="#_7-相关测试" aria-label="Permalink to “7. 相关测试”">​</a></h2><p>Registry 的权限、创建/释放、阈值复位和过滤匹配由以下测试覆盖：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">atest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FrameworksCoreTests:android.view.SurfaceControlRegistryTests</span></span></code></pre></div><p>测试文件：<a href="https://android.googlesource.com/platform/frameworks/base/+/refs/tags/android-16.0.0_r4/core/tests/coretests/src/android/view/SurfaceControlRegistryTests.java" target="_blank" rel="noreferrer"><code>SurfaceControlRegistryTests.java</code></a>。</p>`,68)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};